package com.example.employeeleave;
import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/departments") @org.springframework.security.access.prepost.PreAuthorize("hasRole('ADMIN')") public class DepartmentController {private final DepartmentRepository repo; public DepartmentController(DepartmentRepository r){repo=r;} @GetMapping public List<Department> all(){return repo.findAll();} @PostMapping public ResponseEntity<Department> create(@RequestBody Department d){if(d.getName()==null||d.getName().isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Name is required");if(repo.existsByNameIgnoreCase(d.getName().trim()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Department already exists");d.setName(d.getName().trim());return ResponseEntity.status(HttpStatus.CREATED).body(repo.save(d));} @PutMapping("/{id}") public Department update(@PathVariable Long id,@RequestBody Department d){Department x=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Department not found"));if(d.getName()!=null&&!d.getName().isBlank())x.setName(d.getName().trim());x.setDescription(d.getDescription());return repo.save(x);} @DeleteMapping("/{id}") public ResponseEntity<?> delete(@PathVariable Long id){if(!repo.existsById(id))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Department not found");repo.deleteById(id);return ResponseEntity.noContent().build();}}
